#define CMD_MAP(X) \
    X(INIT,  RUN,   ACTIVE) \
    X(ACTIVE, SAVE,  IDLE) \
    X(IDLE,  LIST,  ACTIVE) \
    X(IDLE,  BYE,   DONE)

// Generate State Enums (S, N)
#define GEN_STATE_ENUM(S, C, N) S, N,
enum State { CMD_MAP(GEN_STATE_ENUM) DONE };

// Macro generates unique command handlers using token pasting
#define TRANSITION_FUNC(S, C, N) \
    int S##_handler(int command_id) { \
        if (command_id == C) return N; \
        return S; /* Stay in current state */ \
    }

// Generates specific state handler implementations
CMD_MAP(TRANSITION_FUNC)

// Transition lookup table (Example: mapping (Current State, Command) to function)
typedef int (*Transition_t)(int);
Transition_t Table[] = {
    #define TABLE_ENTRY(S, C, N) S##_handler,
    CMD_MAP(TABLE_ENTRY)
};
